async function cdqEnsurePdf(id,refresh){
  if(cdqDocumentDownloads.has(id))return cdqDocumentDownloads.get(id);
  const op=(async function(){
    const old=await cdqV19GetRecord('document-pdf',id);
    if(!navigator.onLine){if(old&&old.blob)return old;throw new Error('Ce PDF n’a pas été préparé. Reconnectez Internet et ouvrez-le une fois, puis enregistrez-le sur le téléphone.');}
    // Après une copie, le Blob exact du maître est déjà local. Ne pas attendre
    // la cohérence éventuelle de Google Drive avant la première ouverture.
    if(!refresh&&old&&old.blob&&old.instantCopy&&Number(old.localReadyUntil||0)>Date.now())return old;
    let meta;
    try{meta=await cdqV19Gs('obtenirMetaDocumentPdfCDQ',[id]);}
    catch(e){if(old&&old.blob&&!refresh)return Object.assign({},old,{stale:true});throw e;}
    if(old&&old.blob&&old.revision===meta.revision&&old.blob.size===meta.taille)return old;
    if(meta.taille>CDQ_DOCUMENT_MAX_BYTES||meta.chunks!==Math.ceil(meta.taille/(1024*1024)))throw new Error('Taille PDF invalide.');
    const parts=[];
    for(let i=0;i<meta.chunks;i++){
      const part=await cdqV19Gs('obtenirChunkDocumentPdfCDQ',[id,meta.revision,i]);
      if(part.revision!==meta.revision)throw new Error('Le PDF a changé pendant la préparation. Réessayez.');
      parts.push(cdqV2112Base64ToBytes(part.base64));
    }
    const blob=new Blob(parts,{type:'application/pdf'});
    if(blob.size!==meta.taille||(await blob.slice(0,5).text())!=='%PDF-')throw new Error('Copie PDF incomplète. Réessayez.');
    const rec=Object.assign({},meta,{blob:blob});
    await cdqV19PutRecord('document-pdf',id,rec);return rec;
  })();
  cdqDocumentDownloads.set(id,op);
  try{return await op;}finally{cdqDocumentDownloads.delete(id);}
}

