async function cdqLoadPdfRecord(id){
  let rec=await cdqEnsurePdf(id,false);
  const pending=(await cdqV19QueueGet()).find(a=>a.kind==='pdf-import'&&a.targetId===id);
  if(pending){
    rec=Object.assign({},rec,{blob:new Blob([cdqV2112Base64ToBytes(pending.data)],{type:'application/pdf'})});
  }

  // V23.17 : ne plus reconstruire tout le PDF avec PDF-Lib AVANT l'ouverture.
  // Le lecteur PDF.js ouvre directement le fichier original; cela évite
  // plusieurs secondes de blocage et une forte consommation mémoire Android.
  return rec;
}

